function actionSheet(title,rows){return new Promise(res=>{document.querySelector('#asheet')?.remove();const d=document.createElement('div');d.className='sheet';d.id='asheet';d.innerHTML=`<div class="sheetbox as" role=dialog aria-label="${esc(title)}"><div class=grab></div><h2>${esc(title)}</h2>${rows.map(r=>`<button class="arow ${r.danger?'danger':''}" data-k="${r.k}">${ic(r.icon)}<span>${esc(r.label)}</span></button>`).join('')}<button class="arow cancel" data-k="">Cancel</button></div>`;document.body.appendChild(d);const t0=Date.now();const done=k=>{d.remove();res(k||null)};d.onclick=e=>{if(Date.now()-t0<450)return;const b=e.target.closest('[data-k]');if(b)done(b.dataset.k);else if(e.target===d)done(null)}})}
function undoToast(msg,onUndo,ms=5000){document.querySelector('#undo')?.remove();const u=document.createElement('div');u.id='undo';u.innerHTML=`<span>${esc(msg)}</span><button id=undob>Undo</button>`;document.body.appendChild(u);const t=setTimeout(()=>u.remove(),ms);u.querySelector('#undob').onclick=()=>{clearTimeout(t);u.remove();onUndo()}}
