function presetSize(){const ps=S.imgProvider==='runware'?RW_PRESETS[S.runPreset]:null;let w=+S.imgW||0,h=+S.imgH||0;if((!w||!h||w===h&&w===1024)&&(ps||sdFamily()))return ps?{w:ps.imgW,h:ps.imgH}:{w:832,h:1216};return{w:w||832,h:h||1216}}
