async function renderChats(m){const chats=(await all('chats')).sort((a,b)=>b.updated-a.updated);const chars=Object.fromEntries((await all('chars')).map(c=>[c.id,c]));
 let h='<h1>Chats</h1>';const rm=await recentMap();const favs=Object.values(chars).filter(c=>c.fav).sort((a,b)=>(rm[b.id]||0)-(rm[a.id]||0));h+=`<h2 class=favh>${ic('star')} Favorites</h2>`;if(favs.length){h+='<div class=favrow id=favrow>';for(const c of favs)h+=`<button class=favav data-open="${c.id}" aria-label="Open ${esc(c.name)}"><img class=av src="${await avatarSrc(c)}" alt=""><span class=clip>${esc(c.name)}</span></button>`;h+='</div>'}else h+=`<p class="muted favempty">Tap ☆ on a character to pin it here for quick access.</p>`;h+='<h2>Recent chats</h2>';if(!chats.length)h+='<p class=muted>No chats yet. Open Characters and tap one to start.</p>';
 for(const c of chats){const ch=chars[c.charId];const last=c.messages.at(-1);h+=`<div class=row data-id="${c.id}"><img class=av src="${await avatarSrc(ch)}"><div class=grow><b>${esc(ch?.name||'?')}</b> <small class=muted>${esc(c.title||'')}</small><div class="muted clip">${esc(last?.text?.slice(0,80)||'')}</div></div><button class=x data-del="${c.id}" aria-label="Delete chat">${ic('trash')}</button></div>`}
 m.innerHTML=h;m.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openFav(b.dataset.open));m.querySelectorAll('.row').forEach(r=>r.onclick=e=>{const dl=e.target.closest('[data-del]');if(dl){if(confirm('Delete chat?'))del('chats',dl.dataset.del).then(render);return}openChat(r.dataset.id)})}
