 for(const c of chars)h+=`<div class="ccard row" data-id="${c.id}"><img class=av src="${await avatarSrc(c)}" alt=""><div class=grow><b>${esc(c.name)}</b><div class="muted two">${esc(String(c.description||'').slice(0,200))}</div></div>${starBtn(c.id,c.fav)}<button data-edit="${c.id}" class=ib aria-label="Edit ${esc(c.name)}">${ic('edit')}</button></div>`;
