async function generateCard(idea,genre,tone,opts={}){let out='';const o={...opts};if(genre&&!o.genre)o.genre=genre;if(tone&&!o.tone)o.tone=tone;const spec=genSpec(o);const u=`Idea: ${idea||'surprise me with an original character'}${spec?'\nChosen options (follow all of them):\n'+spec:''}\n\nRemember: ${FEMALE_RULE}`;for await(const t of streamChat([{role:'system',content:GEN_SYS+'\n'+FEMALE_RULE},{role:'user',content:u}],1500))out+=t;const c=parseCard(out);return fixFemale(c,o)}
