 const read=()=>{const o={};for(const [k,,list,multi] of GKEYS){const e=box.querySelector(`[data-g=${k}]`);if(!e)continue;if(multi){const v=[...e.querySelectorAll('.on')].map(b=>b.dataset.v);if(v.length)o[k]=v}else{let v=e.value;if(v==='__r')v=pick(list);if(v)o[k]=v}}return o};
