async function importCard(f){if(!f)return;try{let j,avatarId;if(f.type==='image/png'||f.name.endsWith('.png')){const buf=new Uint8Array(await f.arrayBuffer());j=JSON.parse(decodeURIComponent(escape(atob(pngText(buf)))));avatarId=uid();await put('media',{id:avatarId,type:'image',blob:f})}else j=JSON.parse(await f.text());
 const d=j.data||j;const c={id:uid(),name:d.name||'Imported',description:d.description||'',personality:d.personality||'',scenario:d.scenario||'',first_mes:d.first_mes||'',mes_example:d.mes_example||'',appearance:d.appearance||d.extensions?.appearance||'',imgTags:d.imgTags||d.extensions?.imgTags||'',avatarId};
 if(!confirm(`Import "${c.name}"? Only import characters who are adults (18+).`))return;await put('chars',c);toast('Imported');render()}catch(e){toast('Import failed: '+e.message)}}
function pngText(b){let p=8;const dv=new DataView(b.buffer);let ccv3;while(p<b.length){const len=dv.getUint32(p),type=String.fromCharCode(...b.slice(p+4,p+8));if(type==='tEXt'){const d=b.slice(p+8,p+8+len);const z=d.indexOf(0);const key=new TextDecoder().decode(d.slice(0,z));const val=new TextDecoder('latin1').decode(d.slice(z+1));if(key==='chara')return val;if(key==='ccv3')ccv3=val}p+=12+len}if(ccv3)return ccv3;throw Error('No character data in PNG')}
